import { createInitialGame, createLegacyInitialGame, migrateGameState, FACILITIES, MACHINE_RENTALS, rentMachine, hireEmployee, advanceOneDay, isWorkday, acceptOrder, shipOrder, rejectOrder, cancelRejectedOrder, closePaidOrder, getCurrentOperation, formatDate, getWeekLabel, getWeekAdvanceWindow, assignEmployeeToStage, createMaterialProcurement, assignEmployeeToTask, scheduleShippingTask, bookTemporaryWorker, negotiateTemporaryAgency, TEMP_AGENCY_OFFERS, TEMP_AGENCIES, MARKETING_CAMPAIGNS, setPreferredSupplier, scheduleVacationWeek, getSpaceUse, isHoliday, CONTINUING_COURSES, startContinuingEducation, startApprenticeship, acceptMarketOffer, declineMarketOffer, setOrderPriority, startRework, relocateFacility, INITIAL_INVENTORY, INITIAL_INVENTORY_VALUE, MATERIAL_PRICE_BASELINE, HARDWARE_TOOL_RENTALS, rentHardwareTool, getDailyCapacityHours, getDailyWorkloadPercent, hasManualDayAssignment } from './engine.js';
import { createInitialFinance, createLegacyInitialFinance, migrateFinanceState, issueInvoice, getOpenReceivables, closeMonthlyPeriod, money, processFinancialDay, refreshOverdraftLimit, recordMaterialUse, recordMaterialPurchase, recordMarketingCost, drawForUnpaidCost, drawForMachineLoan, recordTrainingCost, recordToolRental, recordEquipmentLeaseCost, reorderPaymentPriority, recordFacilityRelocation, changeBusinessForm, requestPropertyLoanOffer, acceptPropertyLoanOffer, drawPropertyLoanForPurchase, repayLoanEarly } from './finance.js';
