  if(action==='place-material-order'){const material=document.querySelector('[data-procure-material]')?.value,quantity=Number(document.querySelector('[data-procure-quantity]')?.value),supplierId=document.querySelector('[data-procure-supplier]')?.value,result=createMaterialProcurement(state.game,material,quantity,supplierId);if(!result.ok){showToast(result.reason);return;}const cost=recordMaterialPurchase(state.finance,{[material]:Math.floor(quantity)},state.game.date,supplierId,state.game,result.shippingFee);save();render();showToast(result.task?`Baumarkteinkauf über ${money(cost)} gebucht. Plane den ${result.task.requiredHours}-Stunden-Block per Drag-and-drop.`:`Onlinebestellung über ${money(cost)} gebucht; vsl. ${formatDate(result.order.dueDate)}. Danach muss ein Mitarbeiter die Warenannahme erledigen.`);return;}  if(action==='buy-equipment'){const id=button.dataset.equipment;let result=buyEquipment(state.game,state.finance,id,{installments:false});if(!result.ok&&result.reason==='Nicht genug Bankguthaben'){const item=EQUIPMENT_CATALOG.find(x=>x.id===id),shortfall=Math.max(0,equipmentGrossPrice(item?.price||0)-state.finance.cash),cap=availableEquipmentCredit(state.finance);if(shortfall>0&&confirm(`Bankguthaben reicht nicht. Ratenkauf über ${money(shortfall)} bei 8 % p. a. und 12 Monaten Laufzeit prüfen? Freier Höchstrahmen: ${money(cap)}.`))result=buyEquipment(state.game,state.finance,id,{installments:true});}showToast(result.ok?`${result.asset.name} für ${money(result.grossPrice)} brutto gekauft${result.financed?`; Ratenkauf ${money(result.financed)} vereinbart`:''}.`:result.reason||'Kauf nicht möglich.');save();render();return;}
